def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_threats = 0
    desperate_threats = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 100:
                rich_threats += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_threats += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 20.0))

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / float(WATER_REQ)
    scarce = units < 2.0
    ample = units >= 2.0

    critical = hp <= 2 or no_water_days >= 2
    urgent = hp <= 4 or no_water_days >= 1

    if critical:
        bid = 118.0 if scarce else 96.0
        if rich_threats >= 1:
            bid += 8.0
        return float(min(budget, bid))

    if urgent:
        bid = 78.0 if ample else 92.0
        if highest_prev_bid >= 120:
            bid = max(bid, 88.0)
        elif highest_prev_bid >= 90:
            bid = max(bid, highest_prev_bid + 2.0)
        return float(min(budget, bid))

    if ample:
        bid = 18.0 + 3.0 * desperate_threats
        if avg_prev_bid < 60:
            bid = max(bid, 16.0)
        return float(min(budget, bid))

    bid = 42.0
    if highest_prev_bid >= 130:
        bid = 34.0
    elif highest_prev_bid >= 90:
        bid = min(68.0, highest_prev_bid - 8.0)
    elif highest_prev_bid > 0:
        bid = max(45.0, highest_prev_bid + 1.0)

    if day >= 8 and budget > 120:
        bid += 8.0
    if rich_threats >= 2:
        bid += 5.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer how aggressive the field is.
    prev_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else 0.0

    # Supply pressure: with mid supply, fewer units exist; bid higher.
    # Use a simple scaling between MIN_SUPPLY..MAX_SUPPLY.
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_factor = 1.0
    else:
        supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_factor = max(0.0, min(1.0, supply_factor))

    # If someone bid near max yesterday, assume they will continue strong.
    # Target a bid that slightly undercuts/contests without going to the extreme.
    if highest_prev_bid >= DAILY_SALARY * 1.55:
        base = DAILY_SALARY * (0.85 + 0.1 * supply_factor)  # ~76.5..85.5
        # If my HP is critical, increase willingness.
        if hp <= 2 or no_water_days >= 2:
            base *= 1.15
    else:
        # More moderate field: bid around the upper-middle to secure water.
        base = DAILY_SALARY * (0.65 + 0.25 * supply_factor)  # ~58.5..81
        if hp <= 2 or no_water_days >= 2:
            base *= 1.25

    # Slight reactive bump if we saw a big gap between top bids.
    if highest_prev_bid > 0 and second_prev_bid > 0:
        gap = highest_prev_bid - second_prev_bid
        if gap > DAILY_SALARY * 0.3:
            base += min(DAILY_SALARY * 0.05, gap * 0.15)

    # Never exceed budget; also avoid spending too much when already fine.
    # If HP is comfortable, cap spending.
    if hp >= 6 and no_water_days == 0:
        cap = DAILY_SALARY * 0.7
    elif hp >= 4:
        cap = DAILY_SALARY * 0.85
    else:
        cap = DAILY_SALARY * 0.98

    bid = min(budget, base, cap)

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid conservatively to secure water
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # High pressure scenario: If highest previous bid was very high
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: # If I have good HP, I can try to save or even skip a day
                return min(my_status['budget'], DAILY_SALARY * 0.35)
            # If HP is low (<=3), I am desperate
            return min(my_status['budget'], DAILY_SALARY * 0.95)

        # Moderate pressure scenario: Try to outbid slightly
        return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 2.0))

    # Default bids if no previous bids are available (e.g., Day 1)
    if my_status['hp'] <= 2: # Very low HP, bid aggressively
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    # Default moderate bid
    return min(my_status['budget'], DAILY_SALARY * 0.55)
